export function translate(locale, key, values = {}) {
  const language = messages[LOCALES.includes(locale) ? locale : DEFAULT_LOCALE];
  const template = language[key];
  if (!template) return key;
  return template.replace(/\{(\w+)\}/g, (_, name) => String(values[name] ?? `{${name}}`));
}

export function localeForIntl(locale) {
  return locale === "en-US" ? "en-US" : "zh-CN";
}

export function translateStatus(locale, value) {
  const translated = translate(locale, `status.${value}`);
  return translated === `status.${value}` ? value : translated;
}

export function translateModelTestFailure(locale, code) {
  const keys = {
    "model_test.provider_http_401": "config.provider401",
    "model_test.provider_http_402": "config.provider402",
    "model_test.provider_http_403": "config.provider403",
    "model_test.provider_http_404": "config.provider404",
    "model_test.provider_http_429": "config.provider429",
    "model_test.provider_request_failed": "config.providerRequestFailed",
    "model_test.provider_response_invalid": "config.providerResponseInvalid",
  };
  return translate(locale, keys[code ?? ""] ?? "config.providerUnknown");
}

export function translateEnum(locale, prefix, value) {
  const key = `${prefix}.${value}`;
  const translated = translate(locale, key);
  return translated === key ? value : translated;
}
